      const RPC_URL = window.BEATBOTS_CONFIG.rpc;
      const TREASURY_PUBKEY = "3v2VAud6JVQ62EuRaTRkKuswKJCvgaAUEJce8A1US68d";
      let connection = null;
      let activeProvider = null;
      let activeWalletType = null;
      let userPubkey = null;
      let userSolBalance = 0;

      if (window.solanaWeb3) {
        connection = new window.solanaWeb3.Connection(RPC_URL, "confirmed");
      }

      function getSolanaProvider(type) {
        if (type === 'phantom') {
          if (window.phantom?.solana?.isPhantom) return window.phantom.solana;
          if (window.solana?.isPhantom) return window.solana;
          return null;
        }
        if (type === 'solflare') {
          if (window.solflare?.isSolflare) return window.solflare;
          return null;
        }
        if (type === 'backpack') {
          if (window.backpack) return window.backpack;
          return null;
        }
        return window.solana || null;
      }

      function detectWallets() {
        const phantom = getSolanaProvider('phantom');
        const solflare = getSolanaProvider('solflare');
        const backpack = getSolanaProvider('backpack');

        const pBadge = bbEl('phantom-status-badge');
        const sBadge = bbEl('solflare-status-badge');
        const bBadge = bbEl('backpack-status-badge');

        if (pBadge) pBadge.textContent = phantom ? 'Installed (Ready)' : 'Not Installed';
        if (sBadge) sBadge.textContent = solflare ? 'Installed (Ready)' : 'Not Installed';
        if (bBadge) bBadge.textContent = backpack ? 'Installed (Ready)' : 'Not Installed';
      }

      async function fetchUserBalance(pubkey) {
        if (!connection || !pubkey) return 0;
        try {
          const lamports = await connection.getBalance(pubkey);
          userSolBalance = lamports / window.solanaWeb3.LAMPORTS_PER_SOL;
          return userSolBalance;
        } catch (err) {
          console.warn('RPC balance lookup warning (using mainnet cluster fallback):', err);
          return userSolBalance || 0;
        }
      }

      function updateWalletUIConnected(walletName, pubkeyStr, balanceVal) {
        const walletBtn = bbEl('wallet-connect-btn');
        const walletText = bbEl('wallet-btn-text');
        const shortPk = `${pubkeyStr.slice(0, 4)}...${pubkeyStr.slice(-4)}`;
        
        walletText.innerHTML = `<span class="inline-block w-2 h-2 rounded-full bg-bass-toxic animate-pulse mr-1.5"></span>${walletName} (${shortPk}) • ${balanceVal.toFixed(2)} SOL`;
        walletBtn.classList.replace('from-bass-toxic', 'from-bass-cyan');
        isWalletConnected = true;

        // Update modal info
        const modalWalletEl = bbEl('modal-wallet-address');
        if (modalWalletEl) {
          modalWalletEl.textContent = `${walletName} (${shortPk}) [${balanceVal.toFixed(2)} SOL]`;
        }

        // Dropdown info
        const dropFullAddr = bbEl('dropdown-full-address');
        const dropSolBal = bbEl('dropdown-sol-balance');
        const solscanLink = bbEl('solscan-link');
        if (dropFullAddr) dropFullAddr.textContent = pubkeyStr;
        if (dropSolBal) dropSolBal.textContent = `${balanceVal.toFixed(4)} SOL`;
        if (solscanLink) solscanLink.href = window.BeatBotsMint.explorerAddress(pubkeyStr);
      }

      function updateWalletUIDisconnected() {
        const walletBtn = bbEl('wallet-connect-btn');
        const walletText = bbEl('wallet-btn-text');
        walletText.textContent = 'Connect Solana';
        walletBtn.classList.replace('from-bass-cyan', 'from-bass-toxic');
        isWalletConnected = false;
        activeProvider = null;
        activeWalletType = null;
        userPubkey = null;
        userSolBalance = 0;

        const modalWalletEl = bbEl('modal-wallet-address');
        if (modalWalletEl) modalWalletEl.textContent = 'Not Connected';

        const dropdown = bbEl('wallet-actions-dropdown');
        if (dropdown) dropdown.classList.add('hidden');
      }

      async function connectWalletProvider(type) {
        const provider = getSolanaProvider(type);
        if (!provider) {
          const installUrls = {
            phantom: "https://phantom.app/",
            solflare: "https://solflare.com/",
            backpack: "https://backpack.app/"
          };
          window.open(installUrls[type] || "https://phantom.app/", "_blank");
          return;
        }

        try {
          const resp = await provider.connect();
          activeProvider = provider;
          activeWalletType = type;
          userPubkey = (resp && resp.publicKey) ? resp.publicKey : provider.publicKey;
          
          const pkStr = userPubkey.toBase58 ? userPubkey.toBase58() : userPubkey.toString();
          const walletName = type.charAt(0).toUpperCase() + type.slice(1);
          
          const bal = await fetchUserBalance(userPubkey);
          updateWalletUIConnected(walletName, pkStr, bal);

          // Close modal
          const wModal = bbEl('wallet-modal');
          if (wModal) wModal.classList.add('hidden');

          // Wire provider events
          if (provider.on) {
            provider.on('disconnect', updateWalletUIDisconnected);
            provider.on('accountChanged', async (newPk) => {
              if (newPk) {
                userPubkey = newPk;
                const newBal = await fetchUserBalance(newPk);
                updateWalletUIConnected(walletName, newPk.toString(), newBal);
              } else {
                updateWalletUIDisconnected();
              }
            });
          }
        } catch (err) {
          console.error("Wallet connection cancelled or failed:", err);
          alert(`Wallet connection cancelled: ${err.message || err}`);
        }
      }

      // Wallet button toggle & Modal wiring
